import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorMessage } from "../api/client";
import {
  getAcceptedAnswers,
  getMyAnswers,
  getMyCategories,
  getMyGrade,
  getMyInfo,
  getMyQuestions,
  type AcceptedAnswer,
  type MyAnswer,
  type MyQuestion,
  type Page,
  type Badge,
  type GradeInfo,
  type MyInfo,
} from "../api/mypage";
import { getCategories } from "../api/tag";
import { BADGE_ICON, GRADE_NAME } from "../components/gradeBadge";
import Header from "../components/Header";
import ProfileDetails, { GRADE_LABEL, formatRate } from "../components/ProfileDetails";
import { detailPath } from "../components/questionList";
import { useAuth } from "../hooks/useAuth";
import "./Mypage.css";

const RECENT_ACCEPTED_SIZE = 5;
const BADGE_PREVIEW_SIZE = 3;

interface MypageData {
  me: MyInfo;
  grade: GradeInfo;
  categoryNames: string[];
  questionCount: number;
  answerCount: number;
  acceptedCount: number;
  recentAccepted: AcceptedAnswer[];
}

// 요약 카드에는 획득한 뱃지를 먼저, 남는 자리에 다음으로 노릴 미획득 뱃지를 보여준다.
function previewBadges(badges: Badge[]) {
  return [...badges.filter((b) => b.acquired), ...badges.filter((b) => !b.acquired)].slice(0, BADGE_PREVIEW_SIZE);
}

// 2026-11-12T12:00:00 → 2026.11.12
function formatDate(value: string) {
  return value.slice(0, 10).replaceAll("-", ".");
}

// 활동 수는 목록 API의 totalElements를 쓴다 (size=1로 개수만 받는다).
async function loadMypage(): Promise<MypageData> {
  const [me, grade, setting, categories, questions, answers, accepted] = await Promise.all([
    getMyInfo(),
    getMyGrade(),
    getMyCategories(),
    getCategories(),
    getMyQuestions(0, 1),
    getMyAnswers(0, 1),
    getAcceptedAnswers(0, RECENT_ACCEPTED_SIZE),
  ]);
  return {
    me,
    grade,
    // 카테고리 목록 순서대로 관심 카테고리 이름을 보여준다
    categoryNames: categories.filter((c) => setting.categoryIds.includes(c.categoryId)).map((c) => c.name),
    questionCount: questions.totalElements,
    answerCount: answers.totalElements,
    acceptedCount: accepted.totalElements,
    recentAccepted: accepted.content,
  };
}

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  "body {\n      font-family: 'Noto Sans KR', -apple-system, BlinkMacSystemFont, sans-serif;\n      background-color: #f7f5f0;\n      background-image: radial-gradient(#d1cebe 1.25px, transparent 1.25px);\n      background-size: 20px 20px;\n    }\n    .font-brand {\n      font-family: 'Plus Jakarta Sans', sans-serif;\n    }\n  \n\n    /* Neo-brutalism borders & solid shadow treatments */\n    .neo-border {\n      border: 2.5px solid #111111;\n    }\n    .neo-border-thin {\n      border: 1.5px solid #111111;\n    }\n    .neo-box-shadow {\n      box-shadow: 5px 5px 0px #111111;\n    }\n    .neo-box-shadow-sm {\n      box-shadow: 3px 3px 0px #111111;\n    }\n    .neo-box-shadow-active {\n      box-shadow: 0px 0px 0px #111111;\n      transform: translate(3px, 3px);\n    }\n    .badge-locked {\n      background-image: repeating-linear-gradient(45deg, #e5e7eb, #e5e7eb 5px, #f3f4f6 5px, #f3f4f6 10px);\n    }";

type ActivityTab = "questions" | "answers";
const PAGE_SIZE = 10;
const PAGE_WINDOW = 5;

// 2026-11-11T10:00:00 → "2일 전 (2026.11.11)"
function formatRelative(value: string) {
  const days = Math.floor((Date.now() - new Date(value).getTime()) / 86_400_000);
  let relative = "오늘";
  if (days >= 365) relative = `${Math.floor(days / 365)}년 전`;
  else if (days >= 30) relative = `${Math.floor(days / 30)}개월 전`;
  else if (days >= 7) relative = `${Math.floor(days / 7)}주 전`;
  else if (days >= 1) relative = `${days}일 전`;
  return `${relative} (${formatDate(value)})`;
}

const STATUS_CLASS = {
  accepted: "bg-emerald-500 text-white font-extrabold text-[11px] px-2 py-0.5 neo-border-thin",
  pending: "bg-neutral-200 text-neutral-700 font-bold text-[11px] px-2 py-0.5 neo-border-thin",
  waiting: "bg-amber-100 text-amber-800 font-bold text-[11px] px-2 py-0.5 neo-border-thin",
};

// 질문: 채택완료 / 미채택(답변은 있지만 채택 전) / 답변 대기중(답변 0개)
function QuestionStatus({ item }: { item: MyQuestion }) {
  if (item.accepted) return <span className={STATUS_CLASS.accepted}>채택완료</span>;
  if (item.answerCount === 0) return <span className={STATUS_CLASS.waiting}>답변 대기중</span>;
  return <span className={STATUS_CLASS.pending}>미채택</span>;
}

// 페이지 번호는 현재 페이지 주변으로 최대 PAGE_WINDOW개 보여준다 (page는 0부터).
function pageNumbers(page: number, totalPages: number) {
  const start = Math.max(0, Math.min(page - Math.floor(PAGE_WINDOW / 2), totalPages - PAGE_WINDOW));
  return Array.from({ length: Math.min(PAGE_WINDOW, totalPages) }, (_, i) => start + i);
}

// 내 질문·답변 목록 (REQ-MYPAGE-008, #32): 탭, 최신순, 페이징, 클릭 시 질문 상세로 이동.
// 수정·삭제는 질문 상세에서만 한다 (REQ-QUESTION-006·007).
function MyActivityList({ questionCount, answerCount }: { questionCount?: number; answerCount?: number }) {
  const [tab, setTab] = useState<ActivityTab>("questions");
  const [page, setPage] = useState(0);
  const [result, setResult] = useState<{ tab: ActivityTab; data: Page<MyQuestion> | Page<MyAnswer> } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setError(null);
    const request = tab === "questions" ? getMyQuestions(page, PAGE_SIZE) : getMyAnswers(page, PAGE_SIZE);
    request
      .then((data) => {
        if (!cancelled) setResult({ tab, data });
      })
      .catch((err) => {
        if (!cancelled) setError(getErrorMessage(err, "목록을 불러오지 못했습니다."));
      });
    return () => {
      cancelled = true;
    };
  }, [tab, page]);

  const changeTab = (next: ActivityTab) => {
    if (next === tab) return;
    setTab(next);
    setPage(0);
  };

  // 탭을 바꾼 직후에는 이전 탭 결과를 보여주지 않는다.
  const data = result?.tab === tab ? result.data : null;
  const tabButton = (value: ActivityTab, label: string, count?: number) => {
    const active = tab === value;
    return (
      <button
        aria-selected={active}
        className={
          active
            ? "neo-border bg-white text-black font-extrabold px-6 py-3 border-b-0 neo-box-shadow-sm text-sm sm:text-base translate-y-[2.5px] z-10 flex items-center gap-2"
            : "neo-border bg-neutral-200 hover:bg-neutral-300 text-neutral-600 font-bold px-6 py-2.5 border-b-[2.5px] text-sm sm:text-base transition-colors flex items-center gap-2"
        }
        id={value === "questions" ? "tab-my-questions" : "tab-my-answers"}
        onClick={() => changeTab(value)}
        role="tab"
        type="button"
      >
        <span>{label}</span>
        <span
          className={`${active ? "bg-neutral-900" : "bg-neutral-400"} text-white text-xs px-2 py-0.5 rounded-none font-bold`}
        >
          {count ?? "-"}
        </span>
      </button>
    );
  };

  return (
    <section className="space-y-0" data-purpose="user-history-list">
      {/* Tab Headers */}
      <div className="flex items-end gap-2 px-1" role="tablist">
        {tabButton("questions", "내 질문", questionCount)}
        {tabButton("answers", "내 답변", answerCount)}
      </div>

      {/* Tab Content Card */}
      <div className="bg-white neo-border neo-box-shadow p-5 sm:p-6 relative z-0">
        <div className="pb-4 mb-4 border-b-2 border-neutral-100">
          <p className="text-xs sm:text-sm font-semibold text-neutral-500" data-field="listSummary">
            {"총 "}
            <span className="font-bold text-neutral-900">{data ? data.totalElements : "-"}개</span>
            {`의 작성 ${tab === "questions" ? "질문" : "답변"}이 있습니다. (최신순)`}
          </p>
        </div>

        {error && (
          <p className="py-6 text-center text-sm font-bold text-rose-600" role="alert">
            {error}
          </p>
        )}
        {!data && !error && (
          <p className="py-6 text-center text-sm font-semibold text-neutral-500">불러오는 중이에요…</p>
        )}
        {data && data.content.length === 0 && (
          <p className="py-10 text-center text-sm font-bold text-neutral-500" data-field="emptyList">
            작성한 글이 없습니다
          </p>
        )}

        {data && data.content.length > 0 && (
          <div className="space-y-3.5" data-purpose="history-items">
            {data.content.map((item) => {
              const answer = "answerId" in item ? item : null;
              const question = answer ? null : (item as MyQuestion);
              return (
                <Link
                  className="block p-4 bg-white hover:bg-amber-50/50 neo-border-thin transition-colors group"
                  data-item={answer ? `answer-${answer.answerId}` : `question-${item.questionId}`}
                  key={answer ? `a${answer.answerId}` : `q${item.questionId}`}
                  to={`/question-detail?questionId=${item.questionId}`}
                >
                  <div className="space-y-2">
                    <div className="flex flex-wrap items-center gap-2" data-field="itemStatus">
                      {question ? (
                        <QuestionStatus item={question} />
                      ) : (
                        <>
                          <span className={item.accepted ? STATUS_CLASS.accepted : STATUS_CLASS.pending}>
                            {item.accepted ? "채택됨" : "미채택"}
                          </span>
                          <span className="bg-indigo-100 text-indigo-800 font-bold text-[11px] px-2 py-0.5 neo-border-thin">
                            내 답변
                          </span>
                        </>
                      )}
                    </div>
                    <h3 className="text-base font-extrabold group-hover:text-indigo-600" data-field="itemTitle">
                      {item.title}
                    </h3>
                    <div className="flex flex-wrap items-center gap-3 text-xs font-semibold text-neutral-500">
                      <span>작성일: {formatRelative(item.createdAt)}</span>
                      {question && (
                        <>
                          <span>•</span>
                          <span
                            className={
                              question.answerCount > 0 ? "text-indigo-600 font-bold" : "text-neutral-500 font-bold"
                            }
                            data-field="itemAnswerCount"
                          >
                            답변 {question.answerCount}개
                          </span>
                        </>
                      )}
                      <span>•</span>
                      <span data-field="itemLikes">좋아요 {item.likeCount}</span>
                    </div>
                  </div>
                </Link>
              );
            })}
          </div>
        )}

        {/* BEGIN: Pagination */}
        {data && data.totalPages > 1 && (
          <nav
            aria-label={`${tab === "questions" ? "질문" : "답변"} 목록 페이지네이션`}
            className="mt-8 flex justify-center items-center gap-1.5"
          >
            <button
              aria-label="이전 페이지"
              className="neo-border w-8 h-8 flex items-center justify-center font-bold text-sm bg-white hover:bg-neutral-100 disabled:opacity-40 disabled:bg-neutral-100"
              disabled={page === 0}
              onClick={() => setPage(page - 1)}
              type="button"
            >
              {"<"}
            </button>
            {pageNumbers(page, data.totalPages).map((n) =>
              n === page ? (
                <span
                  aria-current="page"
                  className="neo-border w-8 h-8 flex items-center justify-center font-extrabold text-sm bg-yellow-300 text-black neo-box-shadow-sm"
                  key={n}
                >
                  {n + 1}
                </span>
              ) : (
                <button
                  className="neo-border w-8 h-8 flex items-center justify-center font-bold text-sm bg-white hover:bg-neutral-100 text-neutral-800"
                  key={n}
                  onClick={() => setPage(n)}
                  type="button"
                >
                  {n + 1}
                </button>
              ),
            )}
            <button
              aria-label="다음 페이지"
              className="neo-border w-8 h-8 flex items-center justify-center font-bold text-sm bg-white hover:bg-neutral-100 disabled:opacity-40 disabled:bg-neutral-100"
              disabled={data.last}
              onClick={() => setPage(page + 1)}
              type="button"
            >
              {">"}
            </button>
          </nav>
        )}
        {/* END: Pagination */}
      </div>
    </section>
  );
}

